import json
for name in ['without-augmentation', 'with-autoaugment', 'with-trivialaugment']:
    path = f'pytorch-lightning_ipynb/data-augmentation/autoaugment/{name}.ipynb'
    with open(path) as f:
        nb = json.load(f)
    print('='*80)
    print('NOTEBOOK:', name, '| cells:', len(nb['cells']))
    for i, c in enumerate(nb['cells']):
        src = ''.join(c['source'])
        if c['cell_type'] == 'markdown':
            # print only headings
            for line in src.splitlines():
                if line.strip().startswith('#'):
                    print(f'  [{i}] MD-HEADING: {line.strip()}')
        else:
            first = src.strip().splitlines()[0] if src.strip() else '(empty)'
            print(f'  [{i}] CODE ({len(src)} ch): {first[:100]}')
"

